{"success": true, "image_path": "/app/data/figures/fig_20260522_174826_878375.png", "engine": "tikz", "code": "\documentclass[tikz,border=5pt]{standalone}
\usepackage{tkz-euclide}
\begin{document}
\begin{tikzpicture}
  % 定义三角形顶点：等腰三角形，底边BC水平，顶点A在上方
  \tkzDefPoint(0,0){B}
  \tkzDefPoint(12,0){C}
  % 计算底边中点O（圆心）
  \tkzDefMidPoint(B,C) \tkzGetPoint{O}
  % 计算顶点A：AB=AC=10，BC=12，利用垂直平分线求A
  % 先计算底边上的高：h = sqrt(10^2 - 6^2) = 8
  \tkzDefPoint(6,8){A}
  % 以BC为直径作圆，圆心O，半径6
  \tkzDrawCircle[thick](O,C)
  % 圆O交AB于点D（利用tkz-euclide求交点）
  \tkzInterLC(A,B)(O,C) \tkzGetPoints{D}{D2}
  % 连接CD
  \tkzDrawSegment(C,D)
  % 画三角形ABC
  \tkzDrawPolygon(A,B,C)
  % 标记直角（CD是AB边上的高？实际上CD是圆内接三角形BCD的边，∠BDC是直径所对圆周角=90°）
  \tkzMarkRightAngle[size=0.4](B,D,C)
  % 标注点
  \tkzLabelPoint[below left](B){$B$}
  \tkzLabelPoint[below right](C){$C$}
  \tkzLabelPoint[above](A){$A$}
  \tkzLabelPoint[above left](D){$D$}
  \tkzLabelPoint[below](O){$O$}
  % 可选：画半径OD（虚线）
  \tkzDrawSegment[dashed](O,D)
\end{tikzpicture}
\end{document}"}
